const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, HeadingLevel, Header, AlignmentType, BorderStyle } = require('docx');
const fs = require('fs');

// Helper: create a table cell with text and width
function cell(text, widthPct, bold = false) {
  return new TableCell({
    width: { size: widthPct, type: WidthType.PERCENTAGE },
    children: [new Paragraph({
      children: [new TextRun({ text, bold, font: '微软雅黑' })],
      alignment: AlignmentType.LEFT,
    })],
  });
}

// Milestone table (bilingual)
const milestoneTable = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  columnWidths: [3400, 3200, 3400],
  rows: [
    // Header row
    new TableRow({
      children: [
        cell('里程碑 / Milestone', 34, true),
        cell('中文说明', 32, true),
        cell('English Description', 34, true),
      ],
    }),
    // Row 1
    new TableRow({
      children: [
        cell('需求确认', 34),
        cell('确认项目需求与范围', 32),
        cell('Confirm requirements & scope', 34),
      ],
    }),
    // Row 2
    new TableRow({
      children: [
        cell('原型验证', 34),
        cell('完成原型并验证可行性', 32),
        cell('Complete prototype & validate feasibility', 34),
      ],
    }),
  ],
});

const doc = new Document({
  sections: [
    // === Page 1: Chinese ===
    {
      headers: {
        default: new Header({
          children: [new Paragraph({
            children: [new TextRun({ text: '晨星测试', font: '微软雅黑', bold: true, size: 20 })],
            alignment: AlignmentType.CENTER,
          })],
        }),
      },
      children: [
        new Paragraph({
          children: [new TextRun({ text: '合成项目简报', font: '微软雅黑', bold: true, size: 36 })],
          heading: HeadingLevel.HEADING_1,
          alignment: AlignmentType.CENTER,
          spacing: { after: 200 },
        }),
        new Paragraph({
          children: [new TextRun({ text: '项目名称：晨星（Morning Star）', font: '微软雅黑', size: 24 })],
          spacing: { after: 120 },
        }),
        new Paragraph({
          children: [new TextRun({ text: '目标：本项目为文档测试用途的合成项目，用于验证文档生成流程。', font: '微软雅黑', size: 24 })],
          spacing: { after: 200 },
        }),
        new Paragraph({
          children: [new TextRun({ text: '里程碑计划', font: '微软雅黑', bold: true, size: 28 })],
          heading: HeadingLevel.HEADING_2,
          spacing: { after: 120 },
        }),
        milestoneTable,
        new Paragraph({ text: '', spacing: { after: 200 } }),
        new Paragraph({
          children: [new TextRun({ text: '预算说明', font: '微软雅黑', bold: true, size: 28 })],
          heading: HeadingLevel.HEADING_2,
          spacing: { after: 120 },
        }),
        new Paragraph({
          children: [new TextRun({ text: '本项目当前预算状态为"未知"，尚未获得具体拨款或经费数字。在正式预算获批之前，所有费用相关决策均暂不执行。请勿将"未知"理解为任何具体金额。', font: '微软雅黑', size: 24 })],
          spacing: { after: 120 },
        }),
      ],
    },
    // === Page 2: English ===
    {
      headers: {
        default: new Header({
          children: [new Paragraph({
            children: [new TextRun({ text: '晨星测试', font: '微软雅黑', bold: true, size: 20 })],
            alignment: AlignmentType.CENTER,
          })],
        }),
      },
      children: [
        new Paragraph({
          children: [new TextRun({ text: 'Synthetic Project Brief', font: '微软雅黑', bold: true, size: 36 })],
          heading: HeadingLevel.HEADING_1,
          alignment: AlignmentType.CENTER,
          spacing: { after: 200 },
        }),
        new Paragraph({
          children: [new TextRun({ text: 'Project Name: Morning Star', font: '微软雅黑', size: 24 })],
          spacing: { after: 120 },
        }),
        new Paragraph({
          children: [new TextRun({ text: 'Objective: This is a synthetic project created solely for document testing purposes, to validate the document generation workflow.', font: '微软雅黑', size: 24 })],
          spacing: { after: 200 },
        }),
        new Paragraph({
          children: [new TextRun({ text: 'Milestone Plan', font: '微软雅黑', bold: true, size: 28 })],
          heading: HeadingLevel.HEADING_2,
          spacing: { after: 120 },
        }),
        milestoneTable,
        new Paragraph({ text: '', spacing: { after: 200 } }),
        new Paragraph({
          children: [new TextRun({ text: 'Budget Notice', font: '微软雅黑', bold: true, size: 28 })],
          heading: HeadingLevel.HEADING_2,
          spacing: { after: 120 },
        }),
        new Paragraph({
          children: [new TextRun({ text: 'The budget for this project is currently UNKNOWN. No specific funding amount has been allocated or approved. All financial decisions are on hold until an official budget is confirmed. Do NOT interpret "unknown" as any numerical value.', font: '微软雅黑', size: 24 })],
          spacing: { after: 120 },
        }),
      ],
    },
  ],
});

const outDir = process.env.SKILL_SANDBOX_OUT_DIR || '/workspace';
Packer.toBuffer(doc).then((buf) => {
  const outPath = outDir + '/report.docx';
  fs.writeFileSync(outPath, buf);
  console.log('Written: ' + outPath + ' (' + buf.length + ' bytes)');
});

